<script setup>
import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import{login}from'../stores/auth.js';import{safeLoginRedirect}from'../services/loginRedirect.js'
const username=ref(''),password=ref(''),showPassword=ref(false),error=ref(''),busy=ref(false),router=useRouter(),route=useRoute()
async function submit(event){if(busy.value)return;const fields=new FormData(event.currentTarget);busy.value=true;error.value='';try{await login({username:String(fields.get('username')||''),password:String(fields.get('password')||'')});router.replace(safeLoginRedirect(route.query.redirect))}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><main class="login-page"><section class="login-card"><div class="login-brand">RBC</div><p class="eyebrow">Portal empresarial</p><h1>Benvingut/da</h1><p class="muted">Accediu a Reciclajes Bajo Cinca</p><form @submit.prevent="submit"><label>Nom d’usuari<input v-model="username" name="username" type="text" autocomplete="username" required autofocus></label><label>Contrasenya<input v-model="password" name="password" :type="showPassword?'text':'password'" autocomplete="current-password" required></label><button type="button" class="link" :aria-pressed="showPassword" @click="showPassword=!showPassword">{{showPassword?'Amagar contrasenya':'Mostrar contrasenya'}}</button><div v-if="error" class="alert error" role="alert">{{error}}</div><button class="button primary wide" :disabled="busy">{{busy?'Accedint…':'Iniciar sessió'}}</button><RouterLink class="link" to="/forgot-password">He oblidat la contrasenya</RouterLink></form></section></main></template>
